import re, sys, glob, os
root = sys.argv[1]
def strip_args(s):
    out=[];depth=0;i=0
    while i < len(s):
        if s.startswith('[\\',i): depth+=1; i+=2; continue
        if s.startswith('\\]',i) and depth>0: depth-=1; i+=2; continue
        if depth==0: out.append(s[i])
        i+=1
    return ''.join(out)
decl = re.compile(r'^\s*(?:value\s+)?(?:private\s+)?(trait|object)\s+([A-Za-z_]\w*)')
def parse(f):
    res={}
    try: lines = open(f, encoding='utf-8', errors='replace').read().split('\n')
    except Exception: return res
    i=0
    while i < len(lines):
        m = decl.match(lines[i])
        if not m: i+=1; continue
        name = m.group(2); hdr = lines[i]; j=i+1
        def bal(s): return s.count('{')-s.count('}') + s.count('(')-s.count(')')
        while j < len(lines) and (bal(strip_args(hdr))>0 or re.match(r'\s*(extends|excludes|comprises|where)\b', lines[j])):
            hdr += ' ' + lines[j]; j+=1
        h = re.sub(r'\(\*.*?\*\)', '', strip_args(hdr))
        ext = re.search(r'\bextends\s*(\{[^}]*\}|[A-Za-z_]\w*)', h)
        supers = set(re.findall(r'[A-Za-z_]\w*', ext.group(1))) if ext else set()
        res.setdefault(name, [set(), []])
        res[name][0] |= supers; res[name][1].append(i+1)
        i = j
    return res
libfiles = sorted(set(glob.glob(root+'/Library/**/*.fs[si]', recursive=True) + glob.glob(root+'/ProjectFortress/LibraryBuiltin/**/*.fs[si]', recursive=True)))
base = {}
for f in libfiles:
    for n,(s,ls) in parse(f).items(): base.setdefault(n,set()).update(s)
allf = [f for f in glob.glob(root+'/**/*.fs[si]', recursive=True) if not any(x in f for x in ('/tmp/','/build/','/default_repository/'))]
pairs = [tuple(x.split('/')) for x in sys.argv[2:]]
def closure(sup, n):
    seen=set(); st=[n]
    while st:
        x=st.pop()
        for s in sup.get(x,()):
            if s not in seen: seen.add(s); st.append(s)
    return seen|{n}
for a,b in pairs:
    hits=[]
    for f in sorted(allf):
        own = parse(f)
        sup = dict(base)
        islib = f in libfiles
        for n,(s,ls) in own.items(): sup[n] = s if not islib else base[n]
        for n,(s,ls) in own.items():
            c = closure(sup,n)
            if a in c and b in c: hits.append((n, os.path.relpath(f,root), ls[0]))
    print(f'== below both {a} and {b}: {len(hits)}')
    for h in hits: print('   ', h[0], h[1]+':'+str(h[2]))
EOF
